NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Song of Solomon'

CHAPTERS = {
    1: {
        1: 'Laulujen laulu Salomon kirjoittama.',
        2: 'Hän suudelkoon minua suunsa suudelmilla. Sillä rakkautesi on suloisempi kuin viini.',
        3: 'Suloinen on voiteittesi tuoksu, vuodatettu öljy on nimesi. Sen tähden nuoret neitsyet rakastavat sinua.',
        4: 'Vedä minut mukaasi, rientäkäämme! Kuningas on tuonut minut kammioihinsa. Riemuitsemme ja iloitsemme sinusta ja ylistämme rakkauttasi enemmän kuin viiniä. Vilpittömästi he sinua rakastavat.',
        5: '"Minä olen musta, mutta ihana, te Jerusalemin tyttäret, kuin Keedarin teltat, kuin Salomon seinäverhot.',
        6: 'Älkää katsoko sitä, että minä olen musta, päivän paahtama. Äitini pojat vihastuivat minuun, panivat minut viinitarhojen vartijaksi – omaa viinitarhaani en vartioinut."',
        7: '"Sano minulle sinä, jota sieluni rakastaa, missä laumaasi paimennat, missä annat sen keskipäivällä levätä. Miksi hunnutettuna joutuisin toveriesi laumojen luo!"',
        8: '"Jos et sitä tiedä, sinä naisista kaunein, käy lammasten jälkiä ja kaitse kilejäsi paimenten telttapaikoilla."',
        9: '"Tammaani, joka on faraon vaunujen edessä, sinut, armaani, vertaan.',
        10: 'Ihanat ovat poskesi ketjuineen ja kaulasi helminauhoineen.',
        11: 'Teemme sinulle kultaketjut sekä hopeasta niihin nastat."',
        12: '"Kuninkaan istuessa pöydässään nardukseni levitti tuoksuaan.',
        13: 'Rakkaani on minulle mirhakimppu, joka lepää yön rintojeni välissä.',
        14: 'Rakkaani on kooferpensaan kukkaterttu Een-Gedin viinitarhoista."',
        15: '"Katso, kaunis sinä olet, armaani. Katso, kaunis olet, silmäsi ovat kyyhkyset."',
        16: '"Katso, kaunis sinä olet, rakkaani. Kuinka suloinen, kuinka ihana on vuoteemme!',
        17: 'Huoneittemme seininä ovat setripuut, kattonamme sypressit."',
    },
    2: {
        1: '"Minä olen Saaronin kukka, olen laaksojen lilja."',
        2: '"Kuin lilja orjantappuroiden keskellä, on armaani tyttärien keskellä."',
        3: '"Kuin omenapuu metsän puiden keskellä on rakkaani nuorukaisten keskellä. Minä haluan istua sen varjossa, ja sen hedelmä on suussani makea.',
        4: 'Hän on vienyt minut viinimajaan. Rakkaus on hänellä lippuna ylläni.',
        5: 'Vahvistakaa minua rypälekakuilla, virvoittakaa minua omenilla, sillä minä olen rakkaudesta sairas."',
        6: 'Hänen vasen kätensä on pääni alla, ja hänen oikea kätensä halaa minua.',
        7: 'Minä vannotan teitä, te Jerusalemin tyttäret, gasellien tai kedon peurojen kautta: älkää herätelkö, älkää häiritkö rakkautta, ennen kuin se itse haluaa.',
        8: 'Rakkaani ääni! Katso, tuolla hän tulee hypellen vuorilla ja loikkien kukkuloilla.',
        9: 'Rakkaani on gasellin kaltainen tai nuoren peuran. Katso, tuolla hän seisoo seinämme takana katsellen ikkunasta sisään ja kurkistellen ristikoista.',
        10: 'Rakkaani vastasi ja sanoi minulle: "Nouse, armaani, sinä kaunoiseni, ja tule.',
        11: 'Sillä katso, talvi on väistynyt, sateet ovat ohi ja menneet menojaan.',
        12: 'Kukkaset ovat puhjenneet maahan, laulun aika on tullut, ja metsäkyyhkysen ääni kuuluu maassamme.',
        13: 'Viikunapuu tekee keväthedelmää, viiniköynnökset ovat kukassa ja tuoksuvat. Nouse, armaani, sinä kaunoiseni, ja tule.',
        14: 'Kyyhkyseni, joka piileksit kallionkoloissa ja vuorenjyrkänteillä, anna minun nähdä kasvosi, anna minun kuulla äänesi, sillä suloinen on äänesi ja ihanat ovat kasvosi."',
        15: 'Ottakaamme ketut kiinni, pienet ketut, jotka turmelevat viinitarhoja, sillä viinitarhamme ovat kukassa.',
        16: 'Rakkaani on minun, ja minä hänen. Hän paimentaa liljojen keskellä.',
        17: 'Kunnes päivä kallistuu iltaan ja varjot pakenevat. Kiertele, rakkaani, kuin gaselli, kuin nuori peura tuoksuvilla vuorilla.',
    },
    3: {
        1: 'Yöllä vuoteellani minä etsin häntä, jota sieluni rakastaa. Minä etsin häntä, mutta en löytänyt.',
        2: '"Nousen ja kiertelen kaupunkia, katuja ja toreja, etsin häntä, jota sieluni rakastaa." Etsin, mutta en löytänyt häntä.',
        3: 'Minut kohtasivat vartijat, jotka kaupungilla kiertelevät. "Oletteko nähneet häntä, jota sieluni rakastaa?"',
        4: 'Tuskin olin kulkenut heidän ohitseen, kun löysin hänet, jota sieluni rakastaa. Tartuin häneen enkä hellittänyt hänestä, ennen kuin olin saattanut hänet äitini taloon, synnyttäjäni kammioon.',
        5: 'Minä vannotan teitä, te Jerusalemin tyttäret, gasellien tai kedon peurojen kautta: älkää herätelkö, älkää häiritkö rakkautta, ennen kuin se itse haluaa.',
        6: 'Mikä tuolla tulee erämaasta kuin savupatsaat tuoksuen mirhalta ja suitsukkeelta, kaikenlaisilta kauppiaan hajujauheilta?',
        7: 'Katso, siinä on Salomon kantotuoli ja sen ympärillä kuusikymmentä sankaria, Israelin sankareita,',
        8: 'kaikki miekkamiehiä, sotaan harjoitettuja. Jokaisella on miekka kupeellaan öiden kauhuja vastaan.',
        9: 'Kuningas Salomo teetti itselleen kantotuolin Libanonin puista.',
        10: 'Sen patsaat hän teetti hopeasta, sen selustan kullasta, sen istuimen purppurasta, ja sisältä sen koristeli Jerusalemin tyttärien rakkaus.',
        11: 'Tulkaa ulos, Siionin tyttäret, ja katsokaa kuningas Salomoa, katsokaa kruunua, jolla hänen äitinsä hänet kruunasi hänen hääpäivänään, hänen sydämensä ilonpäivänä.',
    },
    4: {
        1: '"Katso, kaunis sinä olet, armaani. Katso, kaunis sinä olet. Kyyhkyset ovat silmäsi huntusi takana. Hiuksesi ovat kuin vuohilauma, joka laskeutuu Gileadin vuorilta.',
        2: 'Hampaasi ovat kuin lauma kerittyjä lampaita, pesusta nousseita, kaikilla kaksoset, eikä yhtään karitsatonta.',
        3: 'Kuin purppuranauha ovat huulesi, ja suusi on suloinen. Kuin halkaistu granaattiomena on ohimosi huntusi takana.',
        4: 'Kaulasi on kuin Daavidin torni, asevarastoksi rakennettu. Siitä riippuu tuhat kilpeä, kaikki sankarien varustuksia.',
        5: 'Rintasi ovat kuin kaksi nuorta peuraa, kuin gasellikaksoset, jotka käyvät laitumella liljojen keskellä.',
        6: 'Siksi kunnes päivä alenee ja varjot pakenevat, kävelen mirhavuorelle ja suitsukekukkulalle.',
        7: 'Kaikin puolin olet kaunis, armaani. Sinussa ei ole ainoatakaan virhettä."',
        8: '"Tule kanssani Libanonilta, morsiameni, tule kanssani Libanonilta. Lähde pois Amanan huipulta, Senirin ja Hermonin huipuilta, leijonien leposijoilta ja panttereiden vuorilta."',
        9: '"Olet lumonnut minut, siskoni, morsiameni, lumonnut minut yhdellä silmäykselläsi, yhdellä kaulakoristeesi osalla.',
        10: 'Kuinka ihana onkaan rakkautesi, siskoni, morsiameni! Kuinka paljon viiniä suloisempaa on rakkautesi, kaikkia balsameja suloisempi voiteittesi tuoksu!',
        11: 'Huulesi pisaroivat hunajaa, morsiameni. Mesi ja maito ovat kielesi alla, ja vaatteittesi tuoksu on kuin Libanonin tuoksu."',
        12: '"Suljettu puutarha on siskoni, morsiameni, suljettu kaivo, lukittu lähde.',
        13: 'Sinä versot kuin paratiisi, jossa on granaattiomenia sekä erinomaisia hedelmiä, kooferpensaan kukkia ja narduksia,',
        14: 'nardusta ja sahramia, kalmoruokoa ja kanelia sekä kaikenlaisia suitsukepuita, mirhaa ja aloeta sekä kaikkia parhaita balsamikasveja.',
        15: 'Sinä olet puutarhojen lähde, elävien vetten kaivo, jotka Libanonilta virtaavat."',
        16: '"Herää, pohjatuuli, tule, etelätuuli. Puhalla puutarhaani, että sen balsamituoksut tulvahtaisivat. Tulkoon puutarhaansa rakkaani ja syököön sen erinomaisia hedelmiä."',
    },
    5: {
        1: '"Tulen puutarhaani, siskoni, morsiameni. Poimin mirhani ja balsamini, syön mesileipäni ja hunajani, juon viinini ja maitoni." Syökää, ystävät, juokaa, juokaa runsain määrin, rakkaat veljeni.',
        2: 'Minä nukuin, mutta sydämeni valvoi. Kuule, rakkaani kolkuttaa: "Avaa minulle, siskoseni, armaani, kyyhkyseni, puhtoiseni. Sillä pääni on kastetta täynnä, kiharani yön pisaroita."',
        3: '"Olen viittani riisunut; pukisinko sitä enää päälleni? Olen jalkani pessyt; likaisinko ne taas?"',
        4: 'Rakkaani pisti kätensä ovenreiästä sisään. Silloin sydämeni liikkui häntä kohden.',
        5: 'Minä nousin avaamaan rakkaalleni, ja käteni pisaroivat mirhaa ja sormeni sulaa mirhaa ovensalvan kädensijoihin.',
        6: 'Minä avasin rakkaalleni, mutta rakkaani oli kadonnut, mennyt menojaan. Hänen puhuessaan oli sieluni vallannut hämmennys. Etsin häntä, mutta en häntä löytänyt. Huusin häntä, mutta hän ei minulle vastannut.',
        7: 'Minut kohtasivat vartijat, jotka kaupunkia kiertelevät. He löivät minua ja haavoittivat minua. Päällystakin riistivät yltäni muurien vartijat.',
        8: '"Minä vannotan teitä, te Jerusalemin tyttäret: jos löydätte rakkaani, mitä hänelle sanotte? Sanokaa, että minä olen rakkaudesta sairas."',
        9: '"Mikä tekee rakkaasi muita paremmaksi, sinä naisista kaunein? Mikä tekee rakkaasi muita paremmaksi, että meitä näin vannotat?"',
        10: '"Rakkaani on valkoinen ja punainen, kymmentä tuhatta jalompi.',
        11: 'Hänen päänsä on kultaa, puhtainta kultaa, hänen kiharansa kuin palmunlehvät, mustat kuin korppi.',
        12: 'Hänen silmänsä ovat kuin kyyhkyset purojen partaalla, jotka ovat maidossa kylpeneet ja istuvat runsauden ääressä.',
        13: 'Hänen poskensa ovat kuin balsamilava, kuin tuoksuvat voiteet. Hänen huulensa ovat liljat ja pisaroivat sulaa mirhaa.',
        14: 'Hänen käsivartensa ovat kultatangot täynnä krysoliitteja. Hänen lantionsa on safiireilla peitettyä norsunluuta.',
        15: 'Hänen jalkansa ovat marmoripatsaat aitokultaisilla jalustoilla. Hän on näöltään kuin Libanon valiosetripuineen.',
        16: 'Hänen suunsa on sula makeus. Hän on pelkkää suloutta. Sellainen on rakkaani, sellainen on ystäväni, te Jerusalemin tyttäret."',
    },
    6: {
        1: '"Minne rakkaasi on mennyt, sinä naisista kaunein? Minne rakkaasi on kääntynyt? Etsikäämme häntä kanssasi."',
        2: '"Rakkaani on mennyt puutarhaansa, balsamilavojen luo, paimentamaan puutarhoissa ja poimimaan liljoja.',
        3: 'Minä olen rakkaani oma, ja rakkaani on minun – hän, joka paimentaa liljojen keskellä."',
        4: '"Kaunis kuin Tirsa olet sinä, armaani, suloinen kuin Jerusalem, pelottava kuin sotajoukot.',
        5: 'Käännä pois silmäsi minusta, sillä ne kiehtovat minua. Hiuksesi ovat kuin vuohilauma, joka laskeutuu Gileadilta.',
        6: 'Hampaasi ovat kuin lauma uuhia, pesulta nousseita, kaikilla kaksoset, ei yhtään karitsatonta.',
        7: 'Kuin halkaistu granaattiomena on ohimosi huntusi takana.',
        8: 'Kuusikymmentä on kuningatarta ja kahdeksankymmentä sivuvaimoa ja neitsyitä määrättömästi:',
        9: 'yksi ainoa on kyyhkyseni, puhtoiseni, äitinsä ainoa, synnyttäjänsä valittu. Hänet nähdessään tyttäret kiittävät hänen autuuttaan, kuningattaret ja sivuvaimot ylistävät häntä."',
        10: '"Kuka on neito, joka nousee kuin aamunkoi, kauniina kuin kuu, kirkkaana kuin päivänpaiste, pelottavana kuin sotajoukot?"',
        11: '"Pähkinätarhaan menin katselemaan laakson vihreyttä, katsomaan, joko viiniköynnös versoo ja joko granaattipuut kukkivat.',
        12: 'Tietämättäni sieluni asetti minut jalon kansani vaunuihin."',
    },
    7: {
        1: '"Palaa, palaa, suulemitar! Palaa, palaa katsellaksemme sinua!" "Mitä katselette suulemittaressa? Mahanaimin karkeloa."',
        2: '"Kuinka kauniisti astelet kengissäsi, sinä ruhtinaan tytär! Lanteesi kaartuvat kuin kaulakorut, taitajan kätten tekemät.',
        3: 'Povesi on pyöreä malja, josta sekoitettua viiniä älköön puuttuko. Sinun uumasi on vehnäkuhilas, liljojen ympäröimä.',
        4: 'Sinun molemmat rintasi ovat kuin kaksi nuorta peuraa, kuin gasellin kaksoset.',
        5: 'Kaulasi on kuin norsunluutorni. Silmäsi kuin Hesbonin lammikot Bat-Rabbimin portin luona. Nenäsi on kuin Libanonin torni, joka katselee Damaskoon.',
        6: 'Pääsi kohoaa kuin Karmel, ja pääsi palmikot ovat kuin purppura. Kuningas on kiedottu kutreihisi."',
        7: '"Kuinka kaunis olet, kuinka suloinen, sinä rakkaus, riemuinesi! –',
        8: 'Vartalosi on kuin palmupuu, ja rintasi kuin rypäleet.',
        9: 'Minä sanoin: nousen palmupuuhun, tartun sen oksiin. Olkoot silloin rintasi kuin viinirypäleet ja hengityksesi tuoksu kuin omenien tuoksu.',
        10: 'Olkoon suusi kuin hyvä viini." "Viini, joka helposti valahtaa rakkaaseeni ja kostuttaa nukkuvien huulet!',
        11: 'Minä olen rakkaani oma, ja minuun on hänen halunsa."',
        12: '"Tule, rakkaani, lähtekäämme maalle, yöpykäämme kyliin.',
        13: 'Käykäämme varhain viinitarhoihin katsomaan, joko viiniköynnös kukkii ja nuput aukeavat, joko granaattipuut kukkivat. Siellä annan sinulle rakkauteni.',
        14: 'Lemmenmarjat tuoksuvat, ja oviemme edessä kasvaa kaikenlaisia jaloja hedelmiä. Olen säästänyt ne, sekä uudet että vanhat, sinulle, rakkaani."',
    },
    8: {
        1: '"Olisitpa kuin oma veljeni, äitini rintoja imenyt! Tapaisin sinut ulkona, suutelisin sinua, eikä kukaan halveksisi minua.',
        2: 'Johdattaisin sinut, veisin äitini taloon, ja hän neuvoisi minua. Antaisin mausteviiniä juodaksesi, granaattiomenani mehua."',
        3: 'Hänen vasen kätensä on pääni alla, ja hänen oikea kätensä halaa minua.',
        4: 'Minä vannotan teitä, te Jerusalemin tyttäret: älkää herätelkö, älkää häiritkö rakkautta, ennen kuin se itse haluaa.',
        5: 'Kuka tuolla tulee erämaasta rakkaaseensa nojaten? "Omenapuun alla sinut herätin. Siellä sai sinut äitisi kerran, siellä sai sinut synnyttäjäsi.',
        6: 'Pane minut sinetiksi sydämellesi, sinetiksi käsivarrellesi. Sillä rakkaus on väkevä kuin kuolema, ankara kuin helvetti on sen kiivaus, sen hehku on tulen hehku, on polttava liekki.',
        7: 'Eivät suuret vedet voi rakkautta sammuttaa, eivät virrat sitä tulvaansa upottaa. Jos joku tarjoaisi kaikki talonsa tavarat rakkauden hinnaksi, häntä vain halveksittaisiin."',
        8: '"Meillä on pieni sisko, jolla ei ole vielä rintoja. Mitä teemme siskollemme sinä päivänä, jona häntä kositaan?',
        9: 'Jos hän on muuri, rakennamme sen päälle hopealinnan. Jos hän on ovi, suljemme sen setrilaudoilla."',
        10: '"Minä olen muuri, ja rintani ovat kuin tornit; vaan nyt olen hänen silmissään kuin se, joka löysi rauhan."',
        11: '"Salomolla on viinitarha Baal-Haamonissa. Hän on jättänyt viinitarhan vartijoiden huostaan. Sen hedelmistä mies tuo tuhat hopeasekeliä.',
        12: 'Viinitarhani on omassa hallussani. Sinulle, Salomo, tulkoot ne tuhat, ja sen hedelmän vartijoille kaksisataa."',
        13: '"Sinä puutarhani asukas, toverit kuuntelevat ääntäsi. Anna minunkin kuulla sitä."',
        14: '"Riennä, rakkaani, kuin gaselli, kuin nuori peura balsamivuorille."',
    },
}
